117	
118	        const resolvedProjectsFolder = path.resolve(this.config.projectsFolder);
119	
120	        const workspaceResults: WorkspaceCloneResult[] = await Promise.all(
121	            Object.keys(project.Workspaces).map(async (workspaceId): Promise<WorkspaceCloneResult> => {
122	                const destination = this.repoPath(projectId, workspaceId, repositoryId);
123	
124	                // Path-traversal guard: ensure the clone destination stays under projectsFolder.
125	                const resolvedDest = path.resolve(destination);
126	                if (!resolvedDest.startsWith(resolvedProjectsFolder + path.sep)) {
127	                    throw new Error(
128	                        `Security check failed: clone path "${resolvedDest}" is not under ` +
129	                        `projectsFolder "${resolvedProjectsFolder}"`
130	                    );
131	                }
132	
133	                const credentials = this.config.gitCredentials ?? [];
134	                const credential = resolveCredential(repo.Url, credentials, repo.CredentialId);
135	                const host = extractHost(repo.Url);
136	
137	                // When no credential resolves for an HTTPS URL, report a descriptive
138	                // error rather than attempting an unauthenticated clone that would
139	                // likely fail with an unhelpful git error message.
140	                if (credential === null && host !== null) {
141	                    const errorMessage =
142	                        `Repository '${repo.Name}' requires a credential for host '${host}'. ` +
143	                        `Please select a credential in the repository settings.`;
144	                    this.errorLogManager?.append({
145	                        Severity: 'error',
146	                        Source: 'credentials',
147	                        Operation: 'add-repository',
148	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repositoryId },
149	                        Message: errorMessage,
150	                    });
151	                    return {
152	                        workspaceId,
153	                        success: false,
154	                        error: errorMessage,
155	                    };
156	                }
157	
